<?php

namespace parallel;

use Throwable;

/**
 * <div id="class.parallel-future" class="reference"> <h1 class="title">The parallel\Future class</h1>  <div class="partintro"><p class="verinfo">(0.8.0)</p>  <div class="section">    <h2 class="title">Futures</h2>    <p class="simpara">     A Future represents the return value or uncaught exception from a task, and exposes an API for cancellation.    </p>     <div class="example" id="example-1">      <p><strong>示例 #1 Example showing Future as return value</strong></p>      <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$runtime </span><span style="color: #007700">= new </span><span style="color: #9876AA">\parallel\Runtime</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$future  </span><span style="color: #007700">= </span><span style="color: #9876AA">\$runtime</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">run</span><span style="color: #007700">(function(){<br>    return </span><span style="color: #DD0000">"World"</span><span style="color: #007700">;<br>});<br></span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Hello %s\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$future</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">value</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>      </div>      <div class="example-contents"><p>以上示例的输出类似于：</p></div>      <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="cdata"><blockquote style="border:1px gray solid;"><br>Hello&nbsp;World<br></blockquote></div>      </div>     </div>    <p class="simpara">     The behaviour of a future also allows it to be used as a simple synchronization point even where the task does not return a value explicitly.    </p>     <div class="example" id="example-2">      <p><strong>示例 #2 Example showing Future as synchronization point</strong></p>      <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$runtime </span><span style="color: #007700">= new </span><span style="color: #9876AA">\parallel\Runtime</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$future  </span><span style="color: #007700">= </span><span style="color: #9876AA">\$runtime</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">run</span><span style="color: #007700">(function(){<br>    echo </span><span style="color: #DD0000">"in child "</span><span style="color: #007700">;<br>    for (</span><span style="color: #9876AA">\$i </span><span style="color: #007700">= </span><span style="color: #9876AA">0</span><span style="color: #007700">; </span><span style="color: #9876AA">\$i </span><span style="color: #007700">&lt; </span><span style="color: #9876AA">500</span><span style="color: #007700">; </span><span style="color: #9876AA">\$i</span><span style="color: #007700">++) {<br>        if (</span><span style="color: #9876AA">\$i </span><span style="color: #007700">% </span><span style="color: #9876AA">10 </span><span style="color: #007700">== </span><span style="color: #9876AA">0</span><span style="color: #007700">) {<br>            echo </span><span style="color: #DD0000">"."</span><span style="color: #007700">;<br>        }<br>    }<br>    echo </span><span style="color: #DD0000">" leaving child"</span><span style="color: #007700">;<br>});<br><br></span><span style="color: #9876AA">\$future</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">value</span><span style="color: #007700">();<br>echo </span><span style="color: #DD0000">"\nparent continues\n"</span><span style="color: #007700">;<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>      </div>      <div class="example-contents"><p>以上示例的输出类似于：</p></div>      <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="cdata"><blockquote style="border:1px gray solid;"><br>in&nbsp;child&nbsp;..................................................&nbsp;leaving&nbsp;child<br>parent&nbsp;continues<br></blockquote></div>      </div>     </div>  </div>  <div class="section" id="parallel-future.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">final</span>      <span class="modifier">class</span> <strong class="classname">parallel\Future</strong>     </span>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// Resolution </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parallel-future.value.php" class="methodname" style="color:#CC7832">value</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// State </div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parallel-future.cancelled.php" class="methodname" style="color:#CC7832">cancelled</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parallel-future.done.php" class="methodname" style="color:#CC7832">done</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// Cancellation </div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parallel-future.cancel.php" class="methodname" style="color:#CC7832">cancel</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>   }</div>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link parallel\Future::cancel} — Cancellation</li><li>{@link parallel\Future::cancelled} — State Detection</li><li>{@link parallel\Future::done} — State Detection</li><li>{@link parallel\Future::value} — Resolution</li></ul></div>
 * 
 * A Future represents the return value or uncaught exception from a task, and exposes an API for cancellation.
 *
 * The behaviour of a future also allows it to be used as a simple synchronization point even where the task does not
 * return a value explicitly.
 *
 * @see https://www.php.net/manual/en/class.parallel-future.php
 */
final class Future
{
    /* Resolution */

    /**
 * <div id="parallel-future.value" class="refentry"> <div class="refnamediv">  <h1 class="refname">parallel\Future::value</h1>  <p class="verinfo">(0.8.0)</p><p class="refpurpose"><span class="refname">parallel\Future::value</span> — <span class="dc-title">Resolution</span></p> </div> <div class="refsect1 description" id="refsect1-parallel-future.value-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>parallel\Future::value</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="simpara">   Shall return (and if necessary wait for) return from task  </p> </div> <div class="refsect1 exceptions" id="refsect1-parallel-future.value-exceptions">  <h3 class="title">Exceptions</h3>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Future\Error</span> if waiting failed (internal error).   </p>  </div>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Future\Error\Killed</span> if <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.parallel-runtime.php" class="type parallel\Runtime" style="color:#EAB766">parallel\Runtime</a></span> executing task was killed.   </p>  </div>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Future\Error\Cancelled</span> if task was cancelled.   </p>  </div>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Future\Error\Foreign</span> if task raised an unrecognized uncaught exception.   </p>  </div>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall rethrow <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.throwable.php" class="type Throwable" style="color:#EAB766">Throwable</a></span> uncaught in task   </p>  </div> </div></div>
 * 
     * Shall return (and if necessary wait for) return from task
     *
     * @return mixed
     *
     * @throws Future\Error if waiting failed (internal error).
     * @throws Future\Error\Killed if \parallel\Runtime executing task was killed.
     * @throws Future\Error\Cancelled if task was cancelled.
     * @throws Future\Error\Foreign if task raised an unrecognized uncaught exception.
     * @throws Throwable Shall rethrow \Throwable uncaught in task
     */
    public function value() {}

    /* State */

    /**
 * <div id="parallel-future.done" class="refentry"> <div class="refnamediv">  <h1 class="refname">parallel\Future::done</h1>  <p class="verinfo">(0.8.0)</p><p class="refpurpose"><span class="refname">parallel\Future::done</span> — <span class="dc-title">State Detection</span></p> </div> <div class="refsect1 description" id="refsect1-parallel-future.done-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>parallel\Future::done</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Shall indicate if the task is completed  </p> </div></div>
 * 
     * Shall indicate if the task is completed
     * @return bool
     */
    public function done(): bool {}

    /**
 * <div id="parallel-future.cancelled" class="refentry"> <div class="refnamediv">  <h1 class="refname">parallel\Future::cancelled</h1>  <p class="verinfo">(0.9.0)</p><p class="refpurpose"><span class="refname">parallel\Future::cancelled</span> — <span class="dc-title">State Detection</span></p> </div> <div class="refsect1 description" id="refsect1-parallel-future.cancelled-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>parallel\Future::cancelled</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Shall indicate if the task was cancelled  </p> </div></div>
 * 
     * Shall indicate if the task was cancelled
     * @return bool
     */
    public function cancelled(): bool {}

    /* Cancellation */

    /**
 * <div id="parallel-future.cancel" class="refentry"> <div class="refnamediv">  <h1 class="refname">parallel\Future::cancel</h1>  <p class="verinfo">(0.9.0)</p><p class="refpurpose"><span class="refname">parallel\Future::cancel</span> — <span class="dc-title">Cancellation</span></p> </div> <div class="refsect1 description" id="refsect1-parallel-future.cancel-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>parallel\Future::cancel</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">    Shall try to cancel the task  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    If task is running, it will be interrupted.   </span>  </p></blockquote>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Internal function calls in progress cannot be interrupted.   </p>  </div> </div> <div class="refsect1 exceptions" id="refsect1-parallel-future.cancel-exceptions">  <h3 class="title">Exceptions</h3>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Future\Error\Killed</span> if <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.parallel-runtime.php" class="type parallel\Runtime" style="color:#EAB766">parallel\Runtime</a></span> executing task was killed.   </p>  </div>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Future\Error\Cancelled</span> if task was already cancelled.   </p>  </div> </div></div>
 * 
     * Shall try to cancel the task
     * Note: If task is running, it will be interrupted.
     * Warning: Internal function calls in progress cannot be interrupted.
     *
     * @return bool
     *
     * @throws Future\Error\Killed if \parallel\Runtime executing task was killed.
     * @throws Future\Error\Cancelled if task was already cancelled.
     */
    public function cancel(): bool {}
}
